// Build the grader prompt from ONLY what the claim returned.
// The rubric criterion ids are sent verbatim so the model can echo them back:
// guessing ids from criterion names is the most common way a hand-built
// workflow produces output Arena rejects.
const job = $input.first().json.data.job;
const sources = job.input.sources ?? [];

const rubric = job.input.rubric
  .map((c) => `- id: ${c.id}\n  name: ${c.name}\n  maxScore: ${c.maxScore}\n  weight: ${c.weight}${c.reviewInstruction ? `\n  instruction: ${c.reviewInstruction}` : ''}`)
  .join('\n');

const sourceText = sources
  .map((s) => `### source id: ${s.id}\n${s.text}`)
  .join('\n\n');

const instructions = [
  'You are grading one submission against a fixed rubric.',
  'Score EVERY criterion exactly once, using its id verbatim.',
  'Never exceed a criterion maxScore.',
  'Every evidence string MUST be formatted as: [<source id>] <exact quote of at least 12 characters>',
  'The quote must appear verbatim in that source. Do not paraphrase. Do not invent.',
  'Report your honest confidence; a low value triggers a second reviewer, it is not a penalty.',
  'Return ONLY JSON of the shape:',
  '{"criteria":[{"criterionId":"","score":0,"evidence":[""],"issues":[],"confidence":0}],"strengths":[],"priorityImprovements":[],"confidence":0}',
].join('\n');

return [{
  json: {
    jobId: job.jobId,
    rubricIds: job.input.rubric.map((c) => c.id),
    prompt: `${instructions}\n\n## Project\n${job.input.projectTitle} (${job.input.divisionName})\n\n## Rubric\n${rubric}\n\n## Sources\n${sourceText}`,
  },
}];

// Shape and pre-check the model output before spending a lease on it.
// Arena re-validates everything server-side; this only avoids a pointless
// round trip and produces a useful failure reason when the model misbehaves.
const rubricIds = $('Build blind prompt').first().json.rubricIds;
const jobId = $('Build blind prompt').first().json.jobId;

let output;
try {
  output = JSON.parse($json.choices[0].message.content);
} catch (error) {
  return [{ json: { jobId, valid: false, code: 'MODEL_OUTPUT_NOT_JSON', message: String(error).slice(0, 500) } }];
}

const problems = [];
const seen = new Set();
for (const criterion of output.criteria ?? []) {
  if (!rubricIds.includes(criterion.criterionId)) problems.push(`unknown criterion id ${criterion.criterionId}`);
  if (seen.has(criterion.criterionId)) problems.push(`duplicate criterion ${criterion.criterionId}`);
  seen.add(criterion.criterionId);
  for (const evidence of criterion.evidence ?? []) {
    if (!/^\[[^\]]+\]\s+.{12,}/s.test(evidence)) problems.push('evidence missing [source-id] anchor or too short');
  }
}
for (const id of rubricIds) if (!seen.has(id)) problems.push(`missing criterion ${id}`);

return [{
  json: problems.length
    ? { jobId, valid: false, code: 'MODEL_OUTPUT_INVALID', message: problems.slice(0, 3).join('; ').slice(0, 500) }
    : { jobId, valid: true, output },
}];
